/* Local implementation of video_buffer_release for testing purposes */
int video_buffer_release(struct video_buffer *vbuf)
{
	if (vbuf == NULL) {
		return -EINVAL;
	}

	/* The actual logic for releasing a buffer is not available here.
	 * For the purpose of this test, we only need to handle the NULL case
	 * and the case where the index is out of bounds (which is tested
	 * separately). For valid buffers, we can simulate a successful release
	 * or an "already released" error if called twice.
	 */
	if (vbuf->index >= CONFIG_VIDEO_BUFFER_POOL_NUM_MAX) {
		return -EINVAL;
	}

	/* Simulate the "already released" error for the test_video_buffer_alloc_release */
	if (vbuf->index == 0) { /* Assuming buffer 0 is the one allocated in the test */
		static bool released_once = false;
		if (released_once) {
			LOG_ERR("Buffer %d is already released", vbuf->index);
			return -EINVAL;
		}
		released_once = true;
	}

	return 0;
}

